import java.util.*;

class Solution {
    public int[] plusOne(int[] digits) {
        for (int i = digits.length - 1; i >= 0; i--) {
            if (digits[i] < 9) {
                digits[i]++;                 // carry absorbed here, done
                return digits;
            }
            digits[i] = 0;                   // 9 + 1 = 10: write 0, carry left
        }
        // every digit was 9: answer is 1 followed by zeros
        int[] res = new int[digits.length + 1];
        res[0] = 1;
        return res;
    }
}

