class Solution:
    def plusOne(self, digits: List[int]) -> List[int]:
        d = digits[:]
        i = len(d) - 1
        while i >= 0 and d[i] == 9:
            d[i] = 0
            i -= 1
        if i < 0: return [1] + d
        d[i] += 1
        return d

