function plusOne(digits) {
  const res = [];
  let carry = 1;
  for (let i = digits.length - 1; i >= 0; i--) { const s = digits[i] + carry; res.push(s % 10); carry = s >= 10 ? 1 : 0; }
  if (carry) res.push(1);
  return res.reverse();
}
